INSERT INTO public.edudeca_questions (id, subject_id, level, sort_order, stem, options, correct_index, explanation, difficulty_rating, published) VALUES ('l1-phy-01', 'phy', 1, 1, 'Which instrument is used to measure electric current?', '["Voltmeter", "Ammeter", "Barometer", "Thermometer"]'::jsonb, 1, NULL, 1, true);
INSERT INTO public.edudeca_questions (id, subject_id, level, sort_order, stem, options, correct_index, explanation, difficulty_rating, published) VALUES ('l1-che-02', 'che', 1, 2, 'Which of the following is an element?', '["Water", "Carbon dioxide", "Oxygen", "Common salt"]'::jsonb, 2, NULL, 1, true);
INSERT INTO public.edudeca_questions (id, subject_id, level, sort_order, stem, options, correct_index, explanation, difficulty_rating, published) VALUES ('l1-mat-03', 'mat', 1, 3, 'What is the value of 7² − 5²?', '["12", "24", "36", "49"]'::jsonb, 1, NULL, 1, true);
INSERT INTO public.edudeca_questions (id, subject_id, level, sort_order, stem, options, correct_index, explanation, difficulty_rating, published) VALUES ('l1-amat-04', 'amat', 1, 4, 'A shop sells 5 notebooks for ₹250. What is the cost of one notebook?', '["₹40", "₹45", "₹50", "₹55"]'::jsonb, 2, NULL, 1, true);
INSERT INTO public.edudeca_questions (id, subject_id, level, sort_order, stem, options, correct_index, explanation, difficulty_rating, published) VALUES ('l1-bio-05', 'bio', 1, 5, 'Which part of a plant mainly absorbs water from the soil?', '["Flower", "Leaf", "Root", "Fruit"]'::jsonb, 2, NULL, 1, true);
INSERT INTO public.edudeca_questions (id, subject_id, level, sort_order, stem, options, correct_index, explanation, difficulty_rating, published) VALUES ('l1-biotech-06', 'biotech', 1, 6, 'Which microorganism is commonly used in bread-making?', '["Virus", "Yeast", "Algae", "Protozoan"]'::jsonb, 1, NULL, 1, true);
INSERT INTO public.edudeca_questions (id, subject_id, level, sort_order, stem, options, correct_index, explanation, difficulty_rating, published) VALUES ('l1-cs-07', 'cs', 1, 7, 'Which of the following is an output device?', '["Keyboard", "Mouse", "Monitor", "Scanner"]'::jsonb, 2, NULL, 1, true);
INSERT INTO public.edudeca_questions (id, subject_id, level, sort_order, stem, options, correct_index, explanation, difficulty_rating, published) VALUES ('l1-ent-08', 'ent', 1, 8, 'A person who starts and manages a new business is called:', '["Consumer", "Entrepreneur", "Employee", "Creditor"]'::jsonb, 1, NULL, 1, true);
INSERT INTO public.edudeca_questions (id, subject_id, level, sort_order, stem, options, correct_index, explanation, difficulty_rating, published) VALUES ('l1-eng-09', 'eng', 1, 9, 'Choose the word closest in meaning to “rapid.”', '["Slow", "Quick", "Weak", "Quiet"]'::jsonb, 1, NULL, 1, true);
INSERT INTO public.edudeca_questions (id, subject_id, level, sort_order, stem, options, correct_index, explanation, difficulty_rating, published) VALUES ('l1-eco-10', 'eco', 1, 10, 'What is 20% of 450?', '["45", "75", "90", "100"]'::jsonb, 2, NULL, 1, true);
INSERT INTO public.edudeca_questions (id, subject_id, level, sort_order, stem, options, correct_index, explanation, difficulty_rating, published) VALUES ('l1-log-11', 'log', 1, 11, 'Find the next number: 3, 6, 9, 12, ___', '["13", "14", "15", "16"]'::jsonb, 2, NULL, 1, true);
INSERT INTO public.edudeca_questions (id, subject_id, level, sort_order, stem, options, correct_index, explanation, difficulty_rating, published) VALUES ('l1-gk-12', 'gk', 1, 12, 'Which planet is known as the Red Planet?', '["Venus", "Mars", "Jupiter", "Mercury"]'::jsonb, 1, NULL, 1, true);
INSERT INTO public.edudeca_questions (id, subject_id, level, sort_order, stem, options, correct_index, explanation, difficulty_rating, published) VALUES ('l1-fin-13', 'fin', 1, 13, 'Which of the following is money kept aside for future use?', '["Savings", "Tax", "Expense", "Debt"]'::jsonb, 0, NULL, 1, true);
INSERT INTO public.edudeca_questions (id, subject_id, level, sort_order, stem, options, correct_index, explanation, difficulty_rating, published) VALUES ('l2-phy-01', 'phy', 2, 1, 'A body starts from rest and accelerates uniformly at 2 m s⁻² for 5 seconds. What is its final velocity?', '["5 m s⁻¹", "7 m s⁻¹", "10 m s⁻¹", "20 m s⁻¹"]'::jsonb, 2, 'v = u + at = 0 + 2 × 5.', 2, true);
INSERT INTO public.edudeca_questions (id, subject_id, level, sort_order, stem, options, correct_index, explanation, difficulty_rating, published) VALUES ('l2-che-02', 'che', 2, 2, 'Which type of bond is formed when electrons are transferred from one atom to another?', '["Covalent bond", "Ionic bond", "Hydrogen bond", "Metallic bond"]'::jsonb, 1, 'Ionic bonding involves electron transfer.', 2, true);
INSERT INTO public.edudeca_questions (id, subject_id, level, sort_order, stem, options, correct_index, explanation, difficulty_rating, published) VALUES ('l2-mat-03', 'mat', 2, 3, 'If 2x + 7 = 19, what is the value of x?', '["5", "6", "7", "13"]'::jsonb, 1, '2x = 12, so x = 6.', 2, true);
INSERT INTO public.edudeca_questions (id, subject_id, level, sort_order, stem, options, correct_index, explanation, difficulty_rating, published) VALUES ('l2-amat-04', 'amat', 2, 4, 'A taxi charges a fixed amount of ₹50 plus ₹12 per kilometre. What is the total fare for an 8 km journey?', '["₹96", "₹126", "₹146", "₹156"]'::jsonb, 2, 'Fare = 50 + 12 × 8.', 2, true);
INSERT INTO public.edudeca_questions (id, subject_id, level, sort_order, stem, options, correct_index, explanation, difficulty_rating, published) VALUES ('l2-bio-05', 'bio', 2, 5, 'Which cell organelle controls most cellular activities and contains genetic material?', '["Vacuole", "Nucleus", "Ribosome", "Lysosome"]'::jsonb, 1, 'It contains DNA and controls cell activities.', 2, true);
INSERT INTO public.edudeca_questions (id, subject_id, level, sort_order, stem, options, correct_index, explanation, difficulty_rating, published) VALUES ('l2-biotech-06', 'biotech', 2, 6, 'Which technique is used to produce many copies of a specific DNA segment?', '["Fermentation", "Centrifugation", "Polymerase chain reaction", "Chromatography"]'::jsonb, 2, 'PCR amplifies a selected DNA region.', 2, true);
INSERT INTO public.edudeca_questions (id, subject_id, level, sort_order, stem, options, correct_index, explanation, difficulty_rating, published) VALUES ('l2-cs-07', 'cs', 2, 7, 'What is the main purpose of an algorithm?', '["To decorate a computer screen", "To provide step-by-step instructions for solving a problem", "To increase the physical memory of a computer", "To connect a printer to the internet"]'::jsonb, 1, 'An algorithm is a logical sequence of instructions.', 2, true);
INSERT INTO public.edudeca_questions (id, subject_id, level, sort_order, stem, options, correct_index, explanation, difficulty_rating, published) VALUES ('l2-ent-08', 'ent', 2, 8, 'What is a target market?', '["Every person in a country", "The group of customers a business aims to serve", "Only the employees of a business", "The competitors of a business"]'::jsonb, 1, 'It is the intended customer group.', 2, true);
INSERT INTO public.edudeca_questions (id, subject_id, level, sort_order, stem, options, correct_index, explanation, difficulty_rating, published) VALUES ('l2-eng-09', 'eng', 2, 9, 'Choose the sentence with correct subject–verb agreement.', '["The list of items are on the table.", "The list of items is on the table.", "The lists of item is on the table.", "The list of item were on the table."]'::jsonb, 1, 'The subject “list” is singular.', 2, true);
INSERT INTO public.edudeca_questions (id, subject_id, level, sort_order, stem, options, correct_index, explanation, difficulty_rating, published) VALUES ('l2-eco-10', 'eco', 2, 10, 'A shirt marked at ₹1,200 is sold at a discount of 15%. What is its selling price?', '["₹960", "₹1,000", "₹1,020", "₹1,080"]'::jsonb, 2, 'Discount = ₹180; price = ₹1,020.', 2, true);
INSERT INTO public.edudeca_questions (id, subject_id, level, sort_order, stem, options, correct_index, explanation, difficulty_rating, published) VALUES ('l2-log-11', 'log', 2, 11, 'All roses are flowers. Some flowers fade quickly. Which conclusion definitely follows?', '["All roses fade quickly.", "Some roses are not flowers.", "Roses are flowers.", "No flower is a rose."]'::jsonb, 2, 'This directly follows from the statement.', 2, true);
INSERT INTO public.edudeca_questions (id, subject_id, level, sort_order, stem, options, correct_index, explanation, difficulty_rating, published) VALUES ('l2-gk-12', 'gk', 2, 12, 'Which organ of the United Nations is primarily responsible for maintaining international peace and security?', '["General Assembly", "Security Council", "International Court of Justice", "Secretariat"]'::jsonb, 1, 'It has primary responsibility for international peace and security.', 2, true);
INSERT INTO public.edudeca_questions (id, subject_id, level, sort_order, stem, options, correct_index, explanation, difficulty_rating, published) VALUES ('l2-fin-13', 'fin', 2, 13, '₹10,000 is invested at 8% simple interest per annum for 2 years. What interest is earned?', '["₹800", "₹1,200", "₹1,600", "₹1,800"]'::jsonb, 2, 'SI = PRT/100 = 10,000 × 8 × 2/100.', 2, true);
INSERT INTO public.edudeca_questions (id, subject_id, level, sort_order, stem, options, correct_index, explanation, difficulty_rating, published) VALUES ('l3-phy-01', 'phy', 3, 1, 'A 3 kg body moving at 8 m s⁻¹ collides with a stationary 5 kg body. They stick together after collision. What is their common velocity?', '["2 m s⁻¹", "3 m s⁻¹", "4 m s⁻¹", "5 m s⁻¹"]'::jsonb, 1, 'Momentum conservation: 3 × 8 = (3 + 5)v, so v = 3.', 3, true);
INSERT INTO public.edudeca_questions (id, subject_id, level, sort_order, stem, options, correct_index, explanation, difficulty_rating, published) VALUES ('l3-che-02', 'che', 3, 2, 'For the equilibrium: N₂(g) + 3H₂(g) ⇌ 2NH₃(g) Which change favours the formation of ammonia?', '["Decreasing pressure", "Increasing volume", "Increasing pressure", "Adding ammonia"]'::jsonb, 2, 'The product side has fewer moles of gas.', 3, true);
INSERT INTO public.edudeca_questions (id, subject_id, level, sort_order, stem, options, correct_index, explanation, difficulty_rating, published) VALUES ('l3-mat-03', 'mat', 3, 3, 'If the roots of x² − 9x + k = 0 are 4 and 5, what is the value of k?', '["9", "16", "20", "25"]'::jsonb, 2, 'Product of roots = k = 4 × 5.', 3, true);
INSERT INTO public.edudeca_questions (id, subject_id, level, sort_order, stem, options, correct_index, explanation, difficulty_rating, published) VALUES ('l3-amat-04', 'amat', 3, 4, 'The demand for a product is represented by: D = 500 − 20P where D is demand and P is price in rupees. What is the demand when the price is ₹15?', '["100 units", "200 units", "300 units", "400 units"]'::jsonb, 1, 'D = 500 − 20 × 15 = 200.', 3, true);
INSERT INTO public.edudeca_questions (id, subject_id, level, sort_order, stem, options, correct_index, explanation, difficulty_rating, published) VALUES ('l3-bio-05', 'bio', 3, 5, 'A heterozygous tall pea plant, Tt, is crossed with another heterozygous tall plant, Tt. What is the probability of obtaining a dwarf plant?', '["1/4", "1/2", "3/4", "1"]'::jsonb, 0, 'Tt × Tt gives TT, Tt, Tt and tt.', 3, true);
INSERT INTO public.edudeca_questions (id, subject_id, level, sort_order, stem, options, correct_index, explanation, difficulty_rating, published) VALUES ('l3-biotech-06', 'biotech', 3, 6, 'A bacterial plasmid used to carry a foreign gene into a host cell is called:', '["Antibody", "Vector", "Enzyme", "Hormone"]'::jsonb, 1, 'A plasmid vector transfers foreign DNA.', 3, true);
INSERT INTO public.edudeca_questions (id, subject_id, level, sort_order, stem, options, correct_index, explanation, difficulty_rating, published) VALUES ('l3-cs-07', 'cs', 3, 7, 'An AI model performs extremely well on its training data but poorly on new data. This is known as:', '["Encryption", "Overfitting", "Compilation", "Compression"]'::jsonb, 1, 'The model memorises training patterns and fails to generalise.', 3, true);
INSERT INTO public.edudeca_questions (id, subject_id, level, sort_order, stem, options, correct_index, explanation, difficulty_rating, published) VALUES ('l3-ent-08', 'ent', 3, 8, 'A startup has monthly fixed costs of ₹60,000 and earns a contribution of ₹300 per product sold. How many products must it sell to reach the break-even point?', '["100", "150", "200", "300"]'::jsonb, 2, 'Break-even units = 60,000/300.', 3, true);
INSERT INTO public.edudeca_questions (id, subject_id, level, sort_order, stem, options, correct_index, explanation, difficulty_rating, published) VALUES ('l3-eng-09', 'eng', 3, 9, 'Read the statement: The school introduced both additional revision classes and weekly mock tests. Examination results improved. The principal concluded that the mock tests alone caused the improvement. Which is the best evaluation?', '["The conclusion is certain because results improved.", "Revision classes may also have contributed to the improvement.", "Mock tests cannot improve performance.", "Results always improve when two changes are introduced."]'::jsonb, 1, 'Two interventions occurred, so causation cannot be assigned to one alone.', 3, true);
INSERT INTO public.edudeca_questions (id, subject_id, level, sort_order, stem, options, correct_index, explanation, difficulty_rating, published) VALUES ('l3-eco-10', 'eco', 3, 10, 'A train travels half the distance at 50 km h⁻¹ and the remaining half at 75 km h⁻¹. What is its average speed?', '["60 km h⁻¹", "62.5 km h⁻¹", "65 km h⁻¹", "70 km h⁻¹"]'::jsonb, 0, 'For equal distances, average speed = 2ab/(a + b).', 3, true);
INSERT INTO public.edudeca_questions (id, subject_id, level, sort_order, stem, options, correct_index, explanation, difficulty_rating, published) VALUES ('l3-log-11', 'log', 3, 11, 'Five people—P, Q, R, S and T—stand in a line. Q stands immediately to the right of P. R stands at one end. T stands to the left of S. S does not stand next to R. Which arrangement is possible?', '["R, P, Q, T, S", "P, Q, S, T, R", "T, S, R, P, Q", "R, T, S, Q, P"]'::jsonb, 0, 'It satisfies all four placement conditions.', 3, true);
INSERT INTO public.edudeca_questions (id, subject_id, level, sort_order, stem, options, correct_index, explanation, difficulty_rating, published) VALUES ('l3-gk-12', 'gk', 3, 12, 'Which scientific principle explains why a satellite remains in orbit around Earth?', '["Conservation of electric charge", "Gravity provides the centripetal force", "Atmospheric pressure supports the satellite", "Magnetic attraction balances its weight"]'::jsonb, 1, 'Gravity supplies the inward centripetal force.', 3, true);
INSERT INTO public.edudeca_questions (id, subject_id, level, sort_order, stem, options, correct_index, explanation, difficulty_rating, published) VALUES ('l3-fin-13', 'fin', 3, 13, 'A portfolio contains: 60% invested in an asset earning 10% 40% invested in an asset earning 5% What is the total portfolio return?', '["6%", "7%", "8%", "9%"]'::jsonb, 2, 'Weighted return = 0.60 × 10% + 0.40 × 5%.', 3, true);
